package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet has made: an amount (0.00 or more), a date, a note (may be empty) and a
 *  status (starting DRAFT) and, once opened, its number on the sheet. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** Given when opened, the next on its sheet; none while a draft, cleared when voided. */
    @Column(name = "claim_number")
    private Integer number;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId) {
        this.sheetId = sheetId;
        this.personId = personId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public Integer getNumber() {
        return number;
    }

    public void setNumber(Integer number) {
        this.number = number;
    }
}
package net.officefloor.hq.app.claim;

/** A claim as shown: its amount with two decimals, its date as yyyy-mm-dd, its status and its number
 *  (null when it has none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonRepository;

/** The audit line for a saved claim: the event, sheet and user, then the person's name, the amount
 *  (two decimals, as shown) and the date (yyyy-mm-dd); then, when the claim has a number, number=. */
final class ClaimAudit {
    private ClaimAudit() {
    }

    static String line(String event, Claim claim, String user, PersonRepository people) {
        return line(event, claim, claim.getNumber(), user, people);
    }

    static String line(String event, Claim claim, Integer number, String user, PersonRepository people) {
        String person = people.findById(claim.getPersonId()).orElseThrow().getName();
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " person=" + person + " amount=" + shown.amount() + " date=" + shown.date()
                + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records CLAIM_SETTLED once the claim is saved; the signed-in user arrives as X-User. */
public class AuditClaimSettled {
    public void audit(@Val Claim claim, @HttpHeaderParameter("X-User") String user,
            PersonRepository people, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_SETTLED", claim, user, people));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Moves the claim to SETTLED, refusing it when its status does not allow that. */
public class SettleClaim {
    public void apply(@Val Claim claim) throws InvalidClaimStatusException {
        ClaimTransition.to(claim, ClaimStatus.SETTLED);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** Takes the sheet's next claim number. The update locks the sheet's row until the transaction
     *  ends, so claims opened at the same moment are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET claim_numbers = claim_numbers + 1 WHERE id = :sheetId", nativeQuery = true)
    int takeClaimNumber(@Param("sheetId") String sheetId);

    @Query(value = "SELECT claim_numbers FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastClaimNumber(@Param("sheetId") String sheetId);

    /** The claim's status as stored now, read past the loaded entity. */
    @Query(value = "SELECT status FROM claim WHERE id = :id", nativeQuery = true)
    String storedStatus(@Param("id") Long id);
}
package net.officefloor.hq.app.claim;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's claims, newest first. */
public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId, ClaimRepository repository,
            ObjectResponse<ClaimsResponse> response) {
        response.send(ClaimsResponse.from(repository.findBySheetIdOrderByIdDesc(sheetId.trim())));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** A sheet's claims, newest first. */
public record ClaimsResponse(List<ClaimResponse> claims) {

    public static ClaimsResponse from(List<Claim> claims) {
        return new ClaimsResponse(claims.stream().map(ClaimResponse::from).toList());
    }
}
