export function claimDueCents(claim: Claim, rate: string | undefined): bigint | undefined {
  if (claim.status === 'SETTLED') return claim.settledDue === null ? undefined : hundredths(claim.settledDue);
  return rate === undefined ? undefined : dueCents(claim.amount, rate);
}

/** A person's due-total in cents: the fixed dues of their settled claims, plus their open claimed ×
 *  their grade's rate / 100. Undefined for n/a: no rate now and no settled claim with a fixed due. */
export function dueTotalCents(claims: Claim[], rate: string | undefined): bigint | undefined {
  const settled = claims.filter((c) => c.status === 'SETTLED' && c.settledDue !== null);
  const fixed = settled.reduce((n, c) => n + hundredths(c.settledDue!), 0n);
  const live = claims.filter((c) => counts(c) && c.status !== 'SETTLED');
  if (rate === undefined) return settled.length ? fixed : undefined;
  return fixed + dueCents(total(live), rate);
}

